def replay(n: int, events: list[tuple[str, int, int]]) -> list[bool]:
    """Offline connectivity using a segment tree and rollback union-find."""
    queries = [(a, b) for kind, a, b in events if kind == "query"]
    query_count = len(queries)
    if query_count == 0:
        return []

    # The segment tree covers query indices, not all event indices.
    size = 1 << (query_count - 1).bit_length()
    tree = [None] * (2 * size)

    def add_interval(left, right, edge):
        """Record that edge is present for queries in [left, right)."""
        left += size
        right += size
        while left < right:
            if left & 1:
                bucket = tree[left]
                if bucket is None:
                    tree[left] = [edge]
                else:
                    bucket.append(edge)
                left += 1
            if right & 1:
                right -= 1
                bucket = tree[right]
                if bucket is None:
                    tree[right] = [edge]
                else:
                    bucket.append(edge)
            left >>= 1
            right >>= 1

    # Map each currently present edge to its first affected query index.
    active = {}
    time = 0
    for kind, a, b in events:
        if kind == "query":
            time += 1
            continue
        if a == b:
            continue

        edge = (a, b) if a < b else (b, a)
        if kind == "link":
            if edge not in active:
                active[edge] = time
        else:  # "unlink"
            start = active.pop(edge, None)
            if start is not None and start < time:
                add_interval(start, time, edge)

    for edge, start in active.items():
        if start < query_count:
            add_interval(start, query_count, edge)
    del active

    # A root stores its negative component size; other entries store parents.
    # Union by size bounds the depth. No path compression: changes must undo.
    parent = [-1] * n
    history = []
    answers = []

    def visit(node, left, right):
        p = parent
        undo = history
        checkpoint = len(undo)

        bucket = tree[node]
        if bucket is not None:
            for a, b in bucket:
                while p[a] >= 0:
                    a = p[a]
                while p[b] >= 0:
                    b = p[b]
                if a == b:
                    continue

                # Make a the root of the larger component.
                if p[a] > p[b]:
                    a, b = b, a
                undo.append((b, p[b]))
                p[a] += p[b]
                p[b] = a

        if right - left == 1:
            a, b = queries[left]
            if a == b:
                answers.append(True)
            else:
                while p[a] >= 0:
                    a = p[a]
                while p[b] >= 0:
                    b = p[b]
                answers.append(a == b)
        else:
            middle = (left + right) >> 1
            visit(node << 1, left, middle)
            if middle < query_count:
                visit((node << 1) | 1, middle, right)

        # Later unions are undone first, so p[b] is again its direct root.
        while len(undo) > checkpoint:
            b, old_size = undo.pop()
            a = p[b]
            p[a] -= old_size
            p[b] = old_size

    visit(1, 0, size)
    return answers
